"use client"

import * as React from "react"
import { cn } from "@/lib/utils"
import { Slider as SliderPrimitive } from "@base-ui/react/slider"

import "@/styles/slider.styles.css"

function Slider({
  className,
  defaultValue,
  value,
  min = 0,
  max = 100,
  ...props
}: SliderPrimitive.Root.Props) {
  const _values = React.useMemo(() => {
    const currentValue = value ?? defaultValue ?? min
    return Array.isArray(currentValue) ? currentValue : [currentValue]
  }, [value, defaultValue, min])

  return (
    <SliderPrimitive.Root
      className={cn("cn-slider", className)}
      data-slot="slider"
      defaultValue={defaultValue}
      value={value}
      min={min}
      max={max}
      thumbAlignment="edge"
      {...props}
    >
      <SliderPrimitive.Control data-slot="slider-control" className="cn-slider-control">
        <SliderPrimitive.Track data-slot="slider-track" className="cn-slider-track">
          <SliderPrimitive.Indicator data-slot="slider-range" className="cn-slider-range" />
        </SliderPrimitive.Track>
        {Array.from({ length: _values.length }, (_, index) => (
          <SliderPrimitive.Thumb
            data-slot="slider-thumb"
            key={index}
            index={index}
            getAriaLabel={
              props["aria-label"]
                ? () => `${props["aria-label"]}${_values.length > 1 ? ` ${index + 1}` : ""}`
                : undefined
            }
            className="cn-slider-thumb"
          />
        ))}
      </SliderPrimitive.Control>
    </SliderPrimitive.Root>
  )
}

export { Slider }

@layer components {
  .cn-slider {
    width: 100%;
    min-width: 0;
  }
  .cn-slider[data-orientation="vertical"] {
    height: 100%;
    width: auto;
  }
  .cn-slider-control {
    position: relative;
    display: flex;
    align-items: center;
    width: 100%;
    height: calc(24 * var(--cn-unit));
    touch-action: none;
    user-select: none;
  }
  .cn-slider-control[data-orientation="vertical"] {
    flex-direction: column;
    width: calc(24 * var(--cn-unit));
    height: 100%;
    min-height: calc(140 * var(--cn-unit));
  }
  .cn-slider-track {
    position: relative;
    width: 100%;
    height: calc(4 * var(--cn-unit));
    border-radius: 9999px;
    background: var(--cn-border-control);
  }
  .cn-slider-track[data-orientation="vertical"] {
    width: calc(4 * var(--cn-unit));
    height: 100%;
    flex-grow: 1;
  }
  .cn-slider-range {
    height: 100%;
    border-radius: inherit;
    background: var(--cn-primary);
  }
  .cn-slider-range[data-orientation="vertical"] {
    width: 100%;
    height: auto;
  }
  .cn-slider-thumb {
    box-sizing: border-box;
    width: calc(16 * var(--cn-unit));
    height: calc(16 * var(--cn-unit));
    border: 1px solid var(--cn-border-active);
    border-radius: 50%;
    background: var(--cn-surface);
    cursor: grab;
  }
  .cn-slider-thumb[data-dragging] {
    background: var(--cn-surface-pressed);
    cursor: grabbing;
  }
  .cn-slider-thumb:has(input:focus-visible) {
    outline: 2px solid var(--cn-focus-color);
    outline-offset: 2px;
  }
  .cn-slider-thumb input {
    outline: none;
  }
  .cn-slider[data-invalid] .cn-slider-track {
    background: var(--cn-status-destructive-border);
  }
  .cn-slider-thumb[data-invalid] {
    border-color: var(--cn-status-destructive-border);
  }
  .cn-slider[data-disabled] .cn-slider-track {
    background: var(--cn-border-disabled);
  }
  .cn-slider[data-disabled] .cn-slider-range {
    background: var(--cn-text-disabled);
  }
  .cn-slider-thumb[data-disabled] {
    border-color: var(--cn-border-disabled);
    background: var(--cn-surface-disabled);
    cursor: not-allowed;
  }
}
@media (hover: hover) {
  @layer components {
    .cn-slider-thumb:not([data-disabled], [data-dragging]):hover {
      background: var(--cn-surface-hover);
    }
  }
}
@media (pointer: coarse) {
  @layer components {
    .cn-slider-control {
      height: calc(44 * var(--cn-unit));
    }
    .cn-slider-control[data-orientation="vertical"] {
      width: calc(44 * var(--cn-unit));
    }
  }
}
@media (forced-colors: active) {
  .cn-slider-thumb:has(input:focus-visible) {
    outline-color: Highlight;
  }
  .cn-slider-range {
    background: Highlight;
    forced-color-adjust: none;
  }
}
